export const LOGIN_HTTP_ERROR = 'LOGIN_HTTP_ERROR'
export const LOGIN_USERNAME_CHANGE = 'LOGIN_USERNAME_CHANGE'
export const LOGIN_PASSWORD_CHANGE = 'LOGIN_PASSWORD_CHANGE'


export function loginHttpError(error) {
  return {
    type: LOGIN_HTTP_ERROR,
    error: error
  }
}

export function loginUsernameChange(scUsername) {
  return {
    type: LOGIN_USERNAME_CHANGE,
    scUsername: scUsername
  }
}

export function loginPasswordChange(scPassword) {
  return {
    type: LOGIN_PASSWORD_CHANGE,
    scPassword: scPassword
  }
}


export function handleLoginChange(event) {
      
      console.log(event)
      const { name, value } = event.target
      
      if (name === 'scUsername') {
        dispatch(loginUsernameChange(value))
      } else  if (name === 'scPassword') {
        dispatch(loginPasswordChange(value))
      }
          
}


